[PlanningStep(reason='To encapsulate parameters for creating keyed state backends, improving method signature readability and maintainability.', final_code='public class KeyedStateBackendParameters<K> {
    private final Environment env;
    private final JobID jobID;
    private final String operatorIdentifier;
    private final TypeSerializer<K> keySerializer;
    private final int numberOfKeyGroups;
    private final KeyGroupRange keyGroupRange;
    private final TaskKvStateRegistry kvStateRegistry;
    private final TtlTimeProvider ttlTimeProvider;
    private final MetricGroup metricGroup;
    private final Collection<KeyedStateHandle> stateHandles;
    private final CloseableRegistry cancelStreamRegistry;

    public KeyedStateBackendParameters(Environment env, JobID jobID, String operatorIdentifier, TypeSerializer<K> keySerializer, int numberOfKeyGroups, KeyGroupRange keyGroupRange, TaskKvStateRegistry kvStateRegistry, TtlTimeProvider ttlTimeProvider, MetricGroup metricGroup, Collection<KeyedStateHandle> stateHandles, CloseableRegistry cancelStreamRegistry) {
        this.env = env;
        this.jobID = jobID;
        this.operatorIdentifier = operatorIdentifier;
        this.keySerializer = keySerializer;
        this.numberOfKeyGroups = numberOfKeyGroups;
        this.keyGroupRange = keyGroupRange;
        this.kvStateRegistry = kvStateRegistry;
        this.ttlTimeProvider = ttlTimeProvider;
        this.metricGroup = metricGroup;
        this.stateHandles = stateHandles;
        this.cancelStreamRegistry = cancelStreamRegistry;
    }

    // Getters for all fields
    public Environment getEnv() {
        return env;
    }

    public JobID getJobID() {
        return jobID;
    }

    public String getOperatorIdentifier() {
        return operatorIdentifier;
    }

    public TypeSerializer<K> getKeySerializer() {
        return keySerializer;
    }

    public int getNumberOfKeyGroups() {
        return numberOfKeyGroups;
    }

    public KeyGroupRange getKeyGroupRange() {
