+package pdb.symbolserver.ui;
+
+import pdb.symbolserver.SymbolStore;
+
+import javax.swing.*;
+import java.io.Serializable;
+
+public class SymbolServerManager implements Serializable {
+    private final SymbolServerConfigurationPanel symbolServerPanel;
+    SymbolStore localSymbolStore;
+    SymbolServerTableModel tableModel;
+
+    public SymbolServerManager(SymbolServerConfigurationPanel symbolServerPanel) {
+        this.symbolServerPanel = symbolServerPanel;
+    }
+
+    void updateButtonEnablement() {
+        boolean hasLocalSymbolStore = localSymbolStore != null;
+        boolean singleRow = symbolServerPanel.getTable().getSelectedRowCount() == 1;
+        boolean moreThanOneRow = symbolServerPanel.getTable().getRowCount() > 1;
+
+        symbolServerPanel.getRefreshSearchLocationsStatusButton().setEnabled(hasLocalSymbolStore && !tableModel.isEmpty());
+        symbolServerPanel.getMoveLocationUpButton().setEnabled(hasLocalSymbolStore && singleRow && moreThanOneRow);
+        symbolServerPanel.getMoveLocationDownButton().setEnabled(hasLocalSymbolStore && singleRow && moreThanOneRow);
+        symbolServerPanel.getAddLocationButton().setEnabled(hasLocalSymbolStore);
+        symbolServerPanel.getDeleteLocationButton().setEnabled(hasLocalSymbolStore && symbolServerPanel.getTable().getSelectedRowCount() > 0);
+        symbolServerPanel.getSaveSearchLocationsButton().setEnabled(hasLocalSymbolStore && symbolServerPanel.isConfigChanged());
+        symbolServerPanel.updateLayout(hasLocalSymbolStore);
+    }
+
+    void addLocation() {
+        JPopupMenu menu = symbolServerPanel.createAddLocationPopupMenu();
+        menu.show(symbolServerPanel.getAddLocationButton(), 0, 0);
+    }
+
+    void deleteLocation() {
+        int selectedRow = symbolServerPanel.getTable().getSelectedRow();
+        tableModel.deleteRows(symbolServerPanel.getTable().getSelectedRows());
+        if (selectedRow >= 0 && selectedRow < symbolServerPanel.getTable().getRowCount()) {
+            symbolServerPanel.getTable().selectRow(selectedRow);
+        }
+    }
+
+    void refreshSearchLocationStatus() {
+        tableModel.refreshSymbolServerLocationStatus();
+        updateButtonEnablement();
+    }
+}
