+        symbolServerPanel.getSaveSearchLocationsButton().setEnabled(hasLocalSymbolStore && symbolServerPanel.isConfigChanged());
+        symbolServerPanel.updateLayout(hasLocalSymbolStore);
+    }
+
+    void addLocation() {
+        JPopupMenu menu = symbolServerPanel.createAddLocationPopupMenu();
+        menu.show(symbolServerPanel.getAddLocationButton(), 0, 0);
+    }
+
