+                                    e.getMessage());
+                        } catch (InvalidInputException e) {
+                            log.appendMsg("Unable to create function with invalid name " +
+                                    symbol.getName() + ": " + e.getMessage());
+                        }
+                    }
+                } catch (AddressOutOfBoundsException e) {
+                    log.appendMsg(
+                            "Unable to create symbol " + symbol.getName() + ": " + e.getMessage());
+                }
+            }
+        }
+    }
+
+    /**
